#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const unsigned long TARGET_PER_MINUTE = 60;
unsigned long startedAt, lastProductAt, lastReportAt;
unsigned long products = 0, stops = 0;
bool previousSensor = HIGH;
bool stopped = false;
bool buttonRaw = HIGH, buttonStable = HIGH;
unsigned long buttonChangedAt = 0;
uint8_t page = 1;

void showNumber(unsigned long n) {
  display.showNumberDec((int)(n > 9999 ? 9999 : n), false);
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  pinMode(7, INPUT_PULLUP);
  pinMode(6, OUTPUT);
  pinMode(13, OUTPUT);
  digitalWrite(13, LOW);
  Serial.begin(9600);
  display.setBrightness(5);
  startedAt = lastProductAt = millis();
  previousSensor = digitalRead(2);
}

void loop() {
  unsigned long now = millis();
  bool sensor = digitalRead(2);
  if (previousSensor == HIGH && sensor == LOW) {
    ++products;
    lastProductAt = now;
  }
  previousSensor = sensor;

  bool raw = digitalRead(7);
  if (raw != buttonRaw) {
    buttonRaw = raw;
    buttonChangedAt = now;
  }
  if (raw != buttonStable && now - buttonChangedAt >= 40) {
    buttonStable = raw;
    if (buttonStable == LOW) page = (page + 1) % 3;
  }

  bool manual = digitalRead(3) == LOW;
  bool idle = now - lastProductAt >= 30000UL;
  bool alarm = manual || idle;
  if (alarm && !stopped) {
    ++stops;
    Serial.print("STOP event="); Serial.print(stops);
    Serial.print(" time_ms="); Serial.print(now);
    Serial.println(manual ? " manual" : " idle");
    tone(6, 1800);
  }
  if (!alarm && stopped) noTone(6);
  stopped = alarm;
  digitalWrite(13, alarm ? HIGH : LOW);

  unsigned long elapsed = now - startedAt;
  float achievement = elapsed == 0 ? 0.0f :
      (float)products * 6000000.0f / ((float)TARGET_PER_MINUTE * elapsed);
  if (page == 0) showNumber(TARGET_PER_MINUTE);
  else if (page == 2) showNumber(stops);
  else if ((now / 2000UL) % 2 == 0) showNumber(products);
  else showNumber((unsigned long)(achievement + 0.5f));

  if (now - lastReportAt >= 1000UL) {
    lastReportAt = now;
    Serial.print("actual="); Serial.print(products);
    Serial.print(" achievement_percent="); Serial.print(achievement, 1);
    Serial.print(" stops="); Serial.println(stops);
  }
}
